package com.ianblk.zianmobs;
import com.ianblk.zianmobs.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Live client/server comparison, confined to the isolated development scene world. */
public final class CompanionAttackSceneClient {
 private record Frame(String id,int entity,int elapsed,float health){}
 private static volatile Frame frame;private static volatile Throwable failure;private static volatile boolean finished;
 private static boolean dispatched;private static int boot,caseIndex=-1,warmup,started=-1,shotIndex,images,endWait;private static String shown="";
 private static MinecraftServer server;private static ServerPlayer viewer;private static CompanionEntity pet;private static net.minecraft.world.entity.animal.Cow victim;
 private static final List<String> IDS=CompanionAttacks.PROFILES.keySet().stream().sorted().toList();private static List<Integer> milestones=List.of();
 public static void register(){if(Boolean.getBoolean("zianmobs.attackScene")){NeoForge.EVENT_BUS.addListener(CompanionAttackSceneClient::client);NeoForge.EVENT_BUS.addListener(CompanionAttackSceneClient::serverTick);}}
 private static void prepare(){if(pet!=null)Companions.current.store(viewer.getUUID(),false);if(victim!=null)victim.discard();if(++caseIndex>=IDS.size()){finished=true;frame=null;return;}String id=IDS.get(caseIndex);viewer.setLastHurtMob(null);viewer.setLastHurtByMob(null);var service=Companions.current;service.grant(viewer.getUUID(),id,Long.MAX_VALUE);service.summon(viewer,id);pet=service.activeEntity(viewer.getUUID());pet.moveTo(51,viewer.getY(),43,270,0);pet.setYBodyRot(270);pet.setYHeadRot(270);pet.setNoAi(true);victim=EntityType.COW.create(viewer.serverLevel());victim.moveTo(55,viewer.getY(),43,90,0);victim.setNoAi(true);victim.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(100);victim.setHealth(100);victim.setCustomNameVisible(true);viewer.serverLevel().addFreshEntity(victim);warmup=0;started=-1;frame=new Frame(id,pet.getId(),-25,100);}
 private static void setup(MinecraftServer s){if(!s.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).toAbsolutePath().toString().contains("mobs-scene-client"))throw new IllegalStateException("Wrong attack scene world");server=s;CompanionScene.setup(s);viewer=s.getPlayerList().getPlayers().getFirst();var level=s.overworld();double floor=level.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,48,48);for(var e:level.getEntitiesOfClass(LivingEntity.class,new net.minecraft.world.phys.AABB(33,floor-8,28,99,floor+12,70)))if(e instanceof CompanionEntity||e instanceof Snowbone)e.discard();viewer.setGameMode(GameType.SURVIVAL);viewer.removeAllEffects();viewer.setHealth(20);viewer.teleportTo(level,52,floor,39,0,8);level.setDayTime(6000);prepare();}
 private static void serverTick(ServerTickEvent.Post event){if(server==null||event.getServer()!=server||finished||failure!=null)return;try{String id=IDS.get(caseIndex);if(started<0){if(++warmup>=25){viewer.setLastHurtMob(victim);Companions.current.attack(pet,viewer);if(pet.pendingAttack==null)throw new IllegalStateException("Live scene failed to begin attack "+id);started=pet.tickCount;}frame=new Frame(id,pet.getId(),started<0?warmup-25:0,victim.getHealth());}else{int elapsed=pet.tickCount-started;victim.setCustomName(net.minecraft.network.chat.Component.literal(id+" · "+String.format(java.util.Locale.ROOT,"%.1f",victim.getHealth())+" HP"));frame=new Frame(id,pet.getId(),elapsed,victim.getHealth());if(elapsed>=CompanionAttacks.profile(id).duration()+7)prepare();}}catch(Throwable ex){failure=ex;}}
 private static void client(ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(mc.screen instanceof net.minecraft.client.gui.screens.TitleScreen&&++boot==35){mc.createWorldOpenFlows().openWorld("companions-scene",()->mc.stop());return;}if(mc.screen!=null||mc.level==null||mc.player==null||mc.getSingleplayerServer()==null)return;try{if(failure!=null)throw new IllegalStateException("Attack scene failed",failure);mc.options.hideGui=true;mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);mc.options.fov().set(60);if(!dispatched){dispatched=true;mc.getSingleplayerServer().execute(()->{try{setup(mc.getSingleplayerServer());}catch(Throwable ex){failure=ex;}});return;}var f=frame;if(f!=null){if(!shown.equals(f.id())){shown=f.id();shotIndex=0;var profile=CompanionAttacks.profile(shown);var times=new TreeSet<Integer>();times.add(-10);times.add(profile.impacts().getFirst()-1);for(int t:profile.impacts())times.add(t+1);times.add(profile.duration()+2);milestones=List.copyOf(times);}if(shotIndex<milestones.size()&&f.elapsed()>=milestones.get(shotIndex)){int expected=milestones.get(shotIndex++);var entity=mc.level.getEntity(f.entity());if(!(entity instanceof CompanionEntity companion))throw new IllegalStateException("Companion not tracked by client "+f.id());if(expected>=0&&expected<CompanionAttacks.profile(f.id()).duration()){var controller=companion.getAnimatableInstanceCache().getManagerForId(companion.getId()).getAnimationControllers().get("combat");if(controller==null||!controller.isPlayingTriggeredAnimation())throw new IllegalStateException("Attack animation is not active at damage marker "+f.id());}if(expected==CompanionAttacks.profile(f.id()).impacts().getFirst()-1&&f.elapsed()<CompanionAttacks.profile(f.id()).impacts().getFirst()&&f.health()!=100)throw new IllegalStateException("Damage preceded windup");Screenshot.grab(mc.gameDirectory,"attack-"+f.id()+"-"+expected+".png",mc.getMainRenderTarget(),c->{});images++;}}if(finished&&++endWait>=20){if(images<IDS.size()*4)throw new IllegalStateException("Some attack phases were not captured");Files.writeString(mc.gameDirectory.toPath().resolve("attack-scene-result.txt"),"PASS: 16 live owned companions, synced combat controllers active at release markers, windup and recovery, "+images+" captured phases; actual server damage timelines tested separately.\n");mc.stop();}}catch(Throwable ex){ZianMobs.LOGGER.error("ATTACK-SCENE FAIL",ex);try{Files.writeString(mc.gameDirectory.toPath().resolve("attack-scene-result.txt"),"FAIL: "+ex);}catch(Exception ignored){}mc.stop();}}
 private CompanionAttackSceneClient(){}
}
